176: function formatPriorVerdictBlock(criteria: readonly CriterionVerdict[]): string {
177:   if (criteria.length === 0) return "";
178:   const blocks = criteria
179:     .map((c) => `<criterion id="${c.id}" status="${c.status}">${c.evidenceProse}</criterion>`)
180:     .join("\n");
181:   return [
182:     "## Prior verification record",
183:     "",
184:     "The previous attempt produced these per-criterion verdicts. Re-confirm every criterion:",
185:     "- Previously `met`: verify the evidence still holds; if it no longer holds, emit `status=\"regressed\"`.",
186:     "- Previously `unmet`: judge fresh.",
187:     "- Check every criterion for regressions even when it was `met` before.",
188:     "",
189:     "<prior_verdicts>",
190:     blocks,
191:     "</prior_verdicts>",
192:   ].join("\n");
193: }
