198: export async function runVerification(
199:   options: RunVerificationOptions,
200: ): Promise<VerificationResult> {
201:   const { issue, implementerOutput, model, cwd, promptTemplate, git, agent, pstackPrinciples, onToolCall } = options;
202:   const phaseLabel = options.phaseLabel ?? `#${issue.id}`;
203:   const template = promptTemplate ?? DEFAULT_VERIFY_PROMPT_TEMPLATE;
204:   const actualGit = git ?? new ShellGitClient(cwd);
205:   const changes = actualGit.latestChanges(options.baseRef);
206: 
207:   const prompt = template
208:     .replace(/\{issue_id\}/g, String(issue.id))
209:     .replace(/\{issue_title\}/g, issue.title)
210:     .replace(/\{issue_body\}/g, issue.body ?? "")
211:     .replace(/\{implementer_output\}/g, implementerOutput.slice(-8000))
212:     .replace(/\{git_diff\}/g, changes.slice(0, 60000))
213:     .replace(/\{pstack_principles\}/g, pstackPrinciples ?? "")
214:     .replace(/\{prior_verdicts_block\}/g, formatPriorVerdictBlock(options.priorCriteria ?? []))
215:     .replace(/\{validation_context_block\}/g, options.validationContextBlock ?? "");
216: 
217:   // Capture verify prompt before execution if recorder is available
218:   if (options.promptRecorder) {
219:     try {
220:       await options.promptRecorder.recordPrompt({
221:         phase: "verify",
222:         issueId: issue.id,
223:         attempt: options.attempt,
224:         model,
225:         client: options.clientKind ?? "custom",
226:         prompt,
227:       });
228:     } catch (err) {
229:       console.error(`Prompt capture failed for #${issue.id} verify: ${err}`);
230:       throw err;
231:     }
232:   }
233: 
234:   let raw = "";
235:   let execResult: { success: boolean; output: string; error?: string; usage?: AgentExecutionUsage } | undefined;
236:   let criteria: ParsedCriterionVerdict[] = [];
237:   try {
238:     execResult = await runAgentExecution({ prompt, model, cwd, agent, onToolCall, onText: options.onText, onUsage: options.onUsage, phaseLabel });
239:     raw = execResult.output;
240:   } catch (err) {
241:     const errorMsg = (err as Error).message;
242:     options.recordUsage?.({
243:       phase: "verify",
244:       issueId: issue.id,
245:       attempt: options.attempt,
246:       client: options.clientKind ?? "custom",
247:       model,
248:       success: false,
249:       error: errorMsg,
250:     });
251:     console.warn(`⚠ Verifier could not run for #${issue.id}: ${errorMsg}.`);
252:     return {
253:       outcome: { kind: "errored", error: errorMsg },
254:       passed: false,
255:       feedback: "",
256:       criteria,
257:       raw: `Verifier could not run: ${errorMsg}`,
258:     };
259:   }
260: 
261:   if (!execResult.success) {
262:     options.recordUsage?.({
263:       phase: "verify",
264:       issueId: issue.id,
265:       attempt: options.attempt,
266:       client: options.clientKind ?? "custom",
267:       model,
268:       success: false,
269:       error: execResult.error,
270:       usage: execResult.usage,
271:     });
272:     return {
273:       outcome: { kind: "errored", error: execResult.error ?? "execution failed" },
274:       passed: false,
275:       feedback: "",
276:       criteria,
277:       raw: execResult.output,
278:     };
279:   }
280: 
281:   criteria = parseCriterionVerdicts(raw);
282: 
283:   const verdict = raw.match(VERDICT_TAG_PATTERN);
284:   if (!verdict) {
285:     options.recordUsage?.({
286:       phase: "verify",
287:       issueId: issue.id,
288:       attempt: options.attempt,
289:       client: options.clientKind ?? "custom",
290:       model,
291:       success: execResult.success,
292:       error: execResult.error,
293:       usage: execResult.usage,
294:     });
295:     return {
296:       outcome: { kind: "inconclusive", reason: "no <verdict> tag found in verifier output" },
297:       passed: false,
298:       feedback: raw.trim(),
299:       criteria,
300:       raw,
301:     };
302:   }
303: 
304:   const passed = verdict[1]!.toUpperCase() === "PASS";
305:   const after = raw.slice(raw.indexOf(verdict[0]) + verdict[0].length)
306:     .replace(/\n?<promise>(COMPLETE|BLOCKED|INCOMPLETE)<\/promise>/gi, "")
307:     .trim();
308: 
309:   options.recordUsage?.({
310:     phase: "verify",
311:     issueId: issue.id,
312:     attempt: options.attempt,
313:     client: options.clientKind ?? "custom",
314:     model,
315:     success: execResult.success,
316:     error: execResult.error,
317:     usage: execResult.usage,
318:   });
319: 
320:   if (passed) {
321:     return { outcome: { kind: "verified" }, passed: true, feedback: after, criteria, raw };
322:   }
323:   // For FAIL, hand the implementer the full verifier reasoning (per-criterion
324:   // checklist + any after-verdict notes). Just stripping the verdict tag itself
325:   // — using only `after` drops the checklist most models put before the tag.
326:   const failFeedback = raw.replace(verdict[0], "")
327:     .replace(/\n?<promise>(COMPLETE|BLOCKED|INCOMPLETE)<\/promise>/gi, "")
328:     .trim();
329:   return {
330:     outcome: { kind: "rejected", feedback: failFeedback },
331:     passed: false,
332:     feedback: failFeedback,
333:     criteria,
334:     raw,
335:   };
336: }
