444:    * Scores a failed verification to decide whether the branch is worth
445:    * preserving on the remote for a future run. A near-miss (most criteria
446:    * met) preserves; a fundamentally broken implementation does not.
447:    */
448:   static scoreBranchPreservation(
449:     criteria: CriterionVerdict[],
450:   ): { preserve: boolean; reason: string } {
451:     if (criteria.length === 0) {
452:       return { preserve: false, reason: "no criteria to score" };
453:     }
454:     const met = criteria.filter((c) => c.status === "met").length;
455:     const total = criteria.length;
456:     const ratio = met / total;
457:     // Preserve when more than half the criteria passed.
458:     if (ratio > 0.5) {
459:       return { preserve: true, reason: `${met}/${total} criteria met` };
460:     }
461:     return { preserve: false, reason: `only ${met}/${total} criteria met` };
462:   }
