473:     // tip so issues with a `Blocked by ...` dependency see the merge commits
474:     // their predecessors produced. options.baseCommit is captured once at
475:     // loop startup and goes stale as soon as the first merge lands.
476:     const baseCommit = this.options.pinnedBranch
477:       ? this.options.git?.revParse(integratedHeadRef) ?? this.options.baseCommit
478:       : this.options.baseCommit ?? this.options.git?.revParse("HEAD");
479:     const sandbox = this.workspaceManager.createSandbox(String(issue.id), {
480:       isolate: this.options.isolate,
481:       required: this.options.requireSandbox,
482:       baseCommit,
483:     });
484: 
485:     loopRun?.recordTaskMeta(issue.id, {
486:       title: issue.title,
487:       body: issue.body,
488:       worktreePath: sandbox.branch ? sandbox.cwd : "",
489:       branchName: sandbox.branch ?? "",
490:       baseCommit: baseCommit ?? "",
491:     });
492: 
493:     try {
494:       const taskResult = await this.executeTask(issue, sandbox.cwd, baseCommit);
495: 
496:       let merged = false;
497:       // C-1: captures a panic-button kill that occurred during the merger so
498:       // the result reports the user's intent instead of misclassifying the
499:       // kill as a real merge failure.
500:       let mergeManualAction: "retry" | "skip" | "interrupted" | undefined;
501:       if (taskResult.success && taskResult.verified) {
502:         // Push the task branch to remote so the worktree's work is visible
503:         if (sandbox.branch && !this.options.isUndoSet?.()) {
504:           try {
505:             const wtGit = new ShellGitClient(sandbox.cwd);
506:             wtGit.pushSetUpstream("origin", sandbox.branch);
507:             console.log(`  ✓ Pushed task branch ${sandbox.branch} to origin`);
508:           } catch (err) {
509:             console.warn(`  ⚠ Failed to push task branch ${sandbox.branch}: ${(err as Error).message}`);
510:           }
511:         }
512: 
513:         // Check undo state before attempting any merge
514:         if (this.options.isUndoSet?.()) {
