154: export function applyTaskPhaseToWorkerProjection(
155:   state: WorkerProjectionState & { dashboardSelection: DashboardSelection },
156:   event: { issueId: IssueId; to: TaskPhase; meta?: TaskMeta },
157:   at: string,
158: ): Pick<WorkerProjectionState & { dashboardSelection: DashboardSelection }, "workers" | "workerOrder" | "dashboardSelection"> {
159:   const key = workerKey(event.issueId);
160:   const workers = new Map(state.workers);
161:   const existing = workers.get(key) ?? createWorkerRow(event.issueId, event.to);
162:   const phases = existing.phases.has(event.to)
163:     ? existing.phases
164:     : new Map([...existing.phases, [event.to, { contextTokens: null, maxContext: null }]]);
165:   workers.set(key, updateWorkerMeta({ ...existing, phase: event.to, phases, latestAt: at }, event.meta));
166: 
167:   const workerOrder = state.workerOrder.some((issueId) => String(issueId) === key)
168:     ? [...state.workerOrder]
169:     : [...state.workerOrder, event.issueId];
170: 
171:   return {
172:     workers,
173:     workerOrder,
174:     dashboardSelection: withSelection(workerOrder, state.dashboardSelection),
175:   };
176: }
