64: function render(event: LoopRunEvent, sink: ConsoleReporterSink): void {
65:   switch (event.kind) {
66:     case "processesDrained":
67:       sink.log("\n→ Undo confirmed. Running rollback...");
68:       return;
69: 
70:     case "panicUndoAborted":
71:       sink.error(
72:         `  ✗ Process termination timeout: ${event.activeProcesses} active process(es) did not exit within ${Math.round(event.timeoutMs / 1000)} seconds. Rollback aborted to prevent live-writer conflicts.`,
73:       );
74:       return;
75: 
76:     case "snapshotRolledBack":
77:       if (event.success) {
78:         sink.log("\n✓ Rollback successful. Loop-start state restored.");
79:         sink.log(`  ✓ Killed processes: ${event.killedCount}`);
80:         if (event.resetTarget) {
81:           sink.log(`  ✓ Reset to: ${event.resetTarget}`);
82:         }
83:         return;
84:       }
85:       if (event.snapshotRetained && event.snapshotPath) {
86:         let msg = `\n✗ Fatal rollback failure. Snapshot retained at:\n  ${event.snapshotPath}\n  Manual recovery required.`;
87:         if (event.affectedPaths && event.affectedPaths.length > 0) {
88:           msg += `\n  Affected paths:\n    ${event.affectedPaths.join("\n    ")}`;
89:         }
90:         sink.error(msg);
91:         return;
92:       }
93:       sink.error("\n✗ Rollback failed.");
94:       return;
95: 
96:     default:
97:       return;
98:   }
99: }
